import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { GridSystem } from './GridSystem';
import { BuildingEntity } from '../Entity/BuildingEntity';
import { BUILDING_CONFIG } from '../Config/BuildingConfig';
import { HallEvents } from '../HallEvents';
import { gridToWorld } from '../Config/GridConfig';
import type { SpendRequestPayload } from './EconomySystem';

export interface BuildRequestPayload {
    typeId: string;
    gridX: number;
    gridY: number;
}

export interface ClickGridPayload {
    gridX: number;
    gridY: number;
}

export class BuildSystem implements System {

    private _world: World = null!;
    private _grid: GridSystem;

    constructor(grid: GridSystem) {
        this._grid = grid;
    }

    onStart(world: World): void {
        this._world = world;
        world.bus.on(HallEvents.CLICK_GRID, this._onClickGrid, this);
        world.bus.on(HallEvents.BUILD_REQUEST, this._onBuildRequest, this);
    }

    onDestroy(world: World): void {
        world.bus.off(HallEvents.CLICK_GRID, this._onClickGrid, this);
        world.bus.off(HallEvents.BUILD_REQUEST, this._onBuildRequest, this);
        this._world = null!;
    }

    onTick(): void {}

    private _onClickGrid(p: ClickGridPayload): void {
        const b = this._grid.getAt(p.gridX, p.gridY);

        // 空格子 → 请求打开建造菜单
        if (!b) {
            this._world.bus.emit(HallEvents.BUILD_MENU_OPEN, p.gridX, p.gridY);
            return;
        }

        const cfg = BUILDING_CONFIG[b.typeId];
        if (!cfg) return;

        // 有建筑 → 按配置分流
        if (cfg.onClick === 'start_battle') {
            this._world.bus.emit(HallEvents.START_BATTLE);
        } else {
            this._world.bus.emit(HallEvents.COLLECT_REQUEST, { buildingId: b.id });
        }
    }

    private _onBuildRequest(p: BuildRequestPayload): void {
        const cfg = BUILDING_CONFIG[p.typeId];
        if (!cfg) {
            this._world.bus.emit(HallEvents.BUILD_FAILED, { reason: 'unknown_type' });
            return;
        }
        if (this._grid.isOccupied(p.gridX, p.gridY)) {
            this._world.bus.emit(HallEvents.BUILD_FAILED, { reason: 'occupied' });
            return;
        }

        const spend: SpendRequestPayload = {
            amount: cfg.cost,
            source: 'build',
            onSuccess: () => this._completeBuild(p, cfg.id),
            onFail: () => this._world.bus.emit(HallEvents.BUILD_FAILED, { reason: 'insufficient' }),
        };
        this._world.bus.emit(HallEvents.SPEND_REQUEST, spend);
    }

    private _completeBuild(p: BuildRequestPayload, typeId: string): void {
        const cfg = BUILDING_CONFIG[typeId];
        const b = this._world.acquire('building', () => new BuildingEntity());
        b.reset();                        // 池复用必须 reset

        b.typeId = typeId;
        b.gridX = p.gridX;
        b.gridY = p.gridY;

        const world = gridToWorld(p.gridX, p.gridY);
        b.x = world.x;
        b.y = world.y;

        b.recalc(cfg);                    // 算 effectiveIncomePerSecond / Cap

        this._world.add(b);
        this._grid.occupy(b);

        this._world.bus.emit(HallEvents.BUILD_COMPLETED, b);
        this._world.bus.emit(HallEvents.BUILD_SUCCESS, b);
    }
}